"use client";

import { useSession } from "next-auth/react";

export default function Dashboard() {
  const { data: session, status } = useSession();

  if (status === "loading") return <p>Laden...</p>;
  if (!session) return <p>Log in om je dashboard te zien.</p>;

  return (
    <div className="space-y-10">
      <h1 className="text-3xl font-bold">Welkom terug, {session?.user?.email}!</h1>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
        <StatCard title="Totaal Taken" value="24" />
        <StatCard title="Bezig" value="8" />
        <StatCard title="Voltooid" value="10" />
        <StatCard title="Actieve Sprint" value="Sprint 3" />
      </div>
    </div>
  );
}

function StatCard({ title, value }: { title: string; value: string }) {
  return (
    <div className="bg-white p-4 rounded-xl shadow">
      <p className="text-gray-500">{title}</p>
      <h2 className="text-2xl font-bold">{value}</h2>
    </div>
  );
}